133	    @Transactional
134	    public Order shipOrder(String orderId, String trackingCode) {
135	        Order order = getOrder(orderId);
136	
137	        if (order.getStatus() != OrderStatus.PAID) {
138	            throw new OrderException("OPERATION_NOT_ALLOWED", "Order is not paid", HttpStatus.CONFLICT);
139	        }
140	
141	        order.setStatus(OrderStatus.SHIPPED);
142	        order.setTrackingCode(trackingCode);
143	        orderRepository.save(order);
144	
145	        notifyCustomer(order, NotificationType.ORDER_SHIPPED);
146	
147	        return order;
148	    }
149	
150	    @Transactional
151	    public Order deliverOrder(String orderId) {
152	        Order order = getOrder(orderId);
153	
154	        if (order.getStatus() != OrderStatus.SHIPPED) {
155	            throw new OrderException("OPERATION_NOT_ALLOWED", "Order is not shipped", HttpStatus.CONFLICT);
156	        }
157	
158	        order.setStatus(OrderStatus.DELIVERED);
159	        orderRepository.save(order);
160	
161	        return order;
162	    }
163	
164	    @Transactional
165	    public Order cancelOrder(String orderId) {
166	        Order order = getOrder(orderId);
167	
168	        if (order.getStatus() == OrderStatus.SHIPPED || order.getStatus() == OrderStatus.DELIVERED) {
169	            throw new OrderException("OPERATION_NOT_ALLOWED", "Cannot cancel a shipped or delivered order", HttpStatus.CONFLICT);
170	        }
171	
172	        if (order.getStatus() == OrderStatus.CANCELLED) {
173	            // Already cancelled, just return
174	            return order;
175	        }
176	
177	        // If paid, need to restore stock and credit
178	        if (order.getStatus() == OrderStatus.PAID) {
179	            restoreStock(order);
180	            removeCreditFromCustomer(order);
181	        }
182	
183	        order.setStatus(OrderStatus.CANCELLED);
184	        orderRepository.save(order);
185	
186	        notifyCustomer(order, NotificationType.ORDER_CANCELLED);
187	
188	        return order;
189	    }
190	
191	    private void validateStock(Order order) {
192	        for (OrderItem item : order.getItems()) {
193	            Optional<Product> product = productRepository.findById(item.getSku());
194	            if (product.isEmpty() || product.get().getStock() < item.getQuantity()) {
195	                // Cancel order
196	                order.setStatus(OrderStatus.CANCELLED);
197	                orderRepository.save(order);
198	                notifyCustomer(order, NotificationType.ORDER_CANCELLED);
199	                throw new OrderException("INSUFFICIENT_STOCK", "Insufficient stock", HttpStatus.CONFLICT);
200	            }
201	        }
202	    }
203	
204	    private void deductStock(Order order) {
205	        for (OrderItem item : order.getItems()) {
206	            Optional<Product> product = productRepository.findById(item.getSku());
207	            if (product.isPresent()) {
208	                Product p = product.get();
209	                p.setStock(p.getStock() - item.getQuantity());
210	                productRepository.save(p);
211	            }
212	        }
213	    }
214	
215	    private void restoreStock(Order order) {
216	        for (OrderItem item : order.getItems()) {
217	            Optional<Product> product = productRepository.findById(item.getSku());
218	            if (product.isPresent()) {
219	                Product p = product.get();
220	                p.setStock(p.getStock() + item.getQuantity());
221	                productRepository.save(p);
222	            }
223	        }
224	    }
225	
226	    private void addCreditToCustomer(Order order) {
227	        Optional<Customer> customerOpt = customerRepository.findById(order.getCustomerCpf());
228	        Customer customer = customerOpt.orElseGet(() -> new Customer(order.getCustomerCpf(), order.getCustomerEmail()));
229	
230	        BigDecimal credit = order.getSummary().getNextPurchaseCredit();
231	        customer.setCreditBalance(PricingUtil.add(customer.getCreditBalance(), credit));
232	
233	        customerRepository.save(customer);
234	    }
235	
236	    private void removeCreditFromCustomer(Order order) {
237	        Optional<Customer> customerOpt = customerRepository.findById(order.getCustomerCpf());
238	        if (customerOpt.isPresent()) {
239	            Customer customer = customerOpt.get();
240	            BigDecimal credit = order.getSummary().getNextPurchaseCredit();
241	            customer.setCreditBalance(PricingUtil.subtract(customer.getCreditBalance(), credit));
242	            customerRepository.save(customer);
243	        }
244	    }
245	
246	    private void notifyCustomer(Order order, NotificationType type) {
247	        CustomerNotification notification = new CustomerNotification(order.getCustomerCpf(), type, order.getId());
248	        notificationRepository.save(notification);
249	    }
250	}
