216	        for (OrderItem item : order.getItems()) {
217	            Optional<Product> product = productRepository.findById(item.getSku());
218	            if (product.isPresent()) {
219	                Product p = product.get();
220	                p.setStock(p.getStock() + item.getQuantity());
221	                productRepository.save(p);
222	            }
223	        }
224	    }
