226	    private void addCreditToCustomer(Order order) {
227	        Optional<Customer> customerOpt = customerRepository.findById(order.getCustomerCpf());
228	        Customer customer = customerOpt.orElseGet(() -> new Customer(order.getCustomerCpf(), order.getCustomerEmail()));
229	
230	        BigDecimal credit = order.getSummary().getNextPurchaseCredit();
231	        customer.setCreditBalance(PricingUtil.add(customer.getCreditBalance(), credit));
232	
233	        customerRepository.save(customer);
234	    }
