236	    private void removeCreditFromCustomer(Order order) {
237	        Optional<Customer> customerOpt = customerRepository.findById(order.getCustomerCpf());
238	        if (customerOpt.isPresent()) {
239	            Customer customer = customerOpt.get();
240	            BigDecimal credit = order.getSummary().getNextPurchaseCredit();
241	            customer.setCreditBalance(PricingUtil.subtract(customer.getCreditBalance(), credit));
242	            customerRepository.save(customer);
243	        }
244	    }
